#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=5

# Target the terraform repo for every gh call, regardless of where this runs.
export GH_REPO="EduardBargues/software-factory-example-terraform"

banner "Terraform factory — secrets setup"

# ── Stage 1: FACTORY_PAT — basics + permissions ───────────────────────────
stage "GitHub: new fine-grained token — basics & permissions"
say "The terraform factory's tasks use this token to open PRs and trigger"
say "downstream runs — the built-in GITHUB_TOKEN can do neither."
open_url "https://github.com/settings/personal-access-tokens/new"
step "Token name:        FACTORY_PAT — software-factory-example-terraform"
step "Resource owner:    EduardBargues"
step "Expiration:        90 days   (never pick 'No expiration')"
step "Repository access: 'Only select repositories' → select"
step "                   EduardBargues/software-factory-example-terraform  (this repo only)"
say ""
say "Expand 'Permissions → Repository permissions' and set EXACTLY these"
say "(leave every other permission on 'No access'):"
step "Actions ………………… Read and write"
step "Contents ……………… Read and write"
step "Issues …………………… Read and write"
step "Pull requests …… Read and write"
step "Workflows ……………… Read and write"
note "Metadata: Read-only is selected automatically — expected and fine."
note "Don't click 'Generate token' yet — that's the next stage."
pause "Done all of the above? Press Enter."

# ── Stage 2: FACTORY_PAT — generate, store & verify ───────────────────────
stage "FACTORY_PAT: generate & store"
step "Click 'Generate token' at the bottom of the page."
step "Copy the token now — GitHub shows it only once (it starts github_pat_)."
warn "It is NOT printed, saved to disk, or committed — only sent to GitHub Secrets."
ask_secret FACTORY_PAT "Paste the token:"
if [[ -z "${FACTORY_PAT:-}" ]]; then
  warn "No token entered — re-run this wizard once you have it."
else
  set_secret FACTORY_PAT "$FACTORY_PAT"
fi

# ── Stage 3: Anthropic Workload Identity Federation ───────────────────────
stage "Anthropic: Workload Identity Federation"
say "The agent authenticates via GitHub OIDC → Anthropic WIF — no stored API key."
say "These four identifiers are the SAME as your python factory, EXCEPT the"
say "federation rule must also trust THIS repo's OIDC subject."
open_url "https://console.anthropic.com/"
step "Open your Workload Identity Federation settings in the Anthropic Console."
step "Ensure a federation rule trusts GitHub OIDC from:"
step "   repo:EduardBargues/software-factory-example-terraform"
step "(extend the existing rule's repository condition, or add a new rule)."
note "Org / Workspace / Service-account IDs match your python factory."
note "Reference: ../software-factory-example-python/docs/factory/RUNBOOK.md (WIF setup)."
warn "The exact Console navigation may differ from the above — follow the current UI/docs."
ask ANTHROPIC_FEDERATION_RULE_ID "Federation rule id (fdrl_…):"
ask ANTHROPIC_ORGANIZATION_ID    "Organization id (UUID):"
ask ANTHROPIC_SERVICE_ACCOUNT_ID "Service account id (svac_…):"
ask ANTHROPIC_WORKSPACE_ID       "Workspace id (wrkspc_…):"
set_secret ANTHROPIC_FEDERATION_RULE_ID  "$ANTHROPIC_FEDERATION_RULE_ID"
set_secret ANTHROPIC_ORGANIZATION_ID     "$ANTHROPIC_ORGANIZATION_ID"
set_secret ANTHROPIC_SERVICE_ACCOUNT_ID  "$ANTHROPIC_SERVICE_ACCOUNT_ID"
set_secret ANTHROPIC_WORKSPACE_ID        "$ANTHROPIC_WORKSPACE_ID"

# ── Stage 4: AWS testing role (for run-e2e) ───────────────────────────────
stage "AWS: testing role for run-e2e"
say "run-e2e assumes the 'terraform-testing' IAM role via OIDC (no long-lived"
say "keys) to apply examples ephemerally, then destroy. The roles are created by"
say "the bootstrap Terraform; we then store the testing role's ARN here."
say ""
note "One-time, with admin creds (see modules/private/github-oidc/README.md):"
note "  cd modules/private/github-oidc && terraform init && terraform apply"
say ""
if ! confirm "Have you applied modules/private/github-oidc (the roles exist)?"; then
  note "Skipping AWS — apply the bootstrap, then re-run this wizard."
else
  # Try to read the testing role ARN straight from terraform output (run from repo root).
  arn="$(terraform -chdir=modules/private/github-oidc output -json role_arns 2>/dev/null | jq -r '.testing // empty' 2>/dev/null || true)"
  if [[ -n "$arn" ]]; then
    say "Found the terraform-testing role ARN from terraform output:"
    note "  $arn"
    if confirm "Use this ARN?"; then AWS_TESTING_ROLE_ARN="$arn"; fi
  fi
  if [[ -z "${AWS_TESTING_ROLE_ARN:-}" ]]; then
    ask AWS_TESTING_ROLE_ARN "Paste the terraform-testing role ARN:"
  fi
  [[ -n "${AWS_TESTING_ROLE_ARN:-}" ]] && set_secret AWS_TESTING_ROLE_ARN "$AWS_TESTING_ROLE_ARN"
  ask AWS_TESTING_REGION "Testing AWS region [eu-west-1]:"
  [[ -z "${AWS_TESTING_REGION:-}" ]] && AWS_TESTING_REGION="eu-west-1"
  set_var AWS_TESTING_REGION "$AWS_TESTING_REGION"
  note "staging/production role ARNs → wire to the APP repo when its deploy tier lands."
fi

# ── Stage 5: verify ───────────────────────────────────────────────────────
stage "Verify the terraform repo's secrets"
say "Secrets now present on $GH_REPO:"
if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
  have=$(gh secret list 2>/dev/null | awk '{print $1}' || true)
  printf '%s\n' "$have" | sed 's/^/  /'
  say ""
  core="FACTORY_PAT ANTHROPIC_FEDERATION_RULE_ID ANTHROPIC_ORGANIZATION_ID ANTHROPIC_SERVICE_ACCOUNT_ID ANTHROPIC_WORKSPACE_ID"
  missing=""
  for s in $core; do printf '%s\n' "$have" | grep -qx "$s" || missing="$missing $s"; done
  if [[ -n "$missing" ]]; then
    warn "pipeline secrets still missing:$missing"
  else
    printf '  %s✓ all pipeline secrets present%s (explore/implement/review can run)\n' "$GREEN" "$RESET"
  fi
  if printf '%s\n' "$have" | grep -qx "AWS_TESTING_ROLE_ARN"; then
    printf '  %s✓ AWS_TESTING_ROLE_ARN present%s (run-e2e can run)\n' "$GREEN" "$RESET"
  else
    note "AWS_TESTING_ROLE_ARN not set — fine until the first module; needed before run-e2e."
  fi
else
  warn "gh not ready — list manually with: gh secret list --repo $GH_REPO"
fi

finish
}

run_wizard "$@"; exit
